use kino_core::{color::pipeline::{Pipeline,rgba16},effects::Frame,commands::{Session,dispatch},model::Project};use serde_json::json;
#[test]fn old_project_default(){let mut v=serde_json::to_value(Project::default()).unwrap();v.as_object_mut().unwrap().remove("color_pipeline");let p:Project=serde_json::from_value(v).unwrap();assert!(!p.color_pipeline.enabled)}
#[test]fn pipeline_settings_invalid(){for p in [Pipeline{enabled:true,working_gamut:99,..Default::default()},Pipeline{reference_white:0.,..Default::default()},Pipeline{input_transfer:99,..Default::default()}]{assert!(p.validate().is_err())}}
#[test]fn rgba16_keeps_precision(){let f=Frame{w:1024,h:1,d:(0..1024).flat_map(|i|[i as f32/1023.,0.,0.,1.]).collect()};let b=rgba16(&f).unwrap();let vals:std::collections::HashSet<_>=b.chunks_exact(8).map(|v|u16::from_le_bytes([v[0],v[1]])).collect();assert_eq!(vals.len(),1024);assert!(rgba16(&Frame{w:1,h:1,d:vec![f32::NAN;4]}).is_err())}
#[test]fn working_composite_linear(){let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0}})).unwrap();for color in [[0.,0.,0.],[1.,1.,1.]]{let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].as_str().unwrap().to_string();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"solid","color":color,"start":0,"duration":1})).unwrap()["clip_id"].as_str().unwrap().to_string();if color[0]>0.{dispatch(&mut s,"set_property",&json!({"clip_id":c,"property":"opacity","value":0.5})).unwrap();}}let mut f=kino_core::render::render_frame(&s.project,0.,&s.cache).unwrap();assert!((f.d[0]-0.5).abs()<1e-6);kino_core::color::pipeline::output(&s.project,&mut f).unwrap();assert!((f.d[0]-0.7353569).abs()<1e-6)}
